import json, subprocess, os, tempfile, itertools
from chown import chown_syntax_spec
from InputOutputInfoGeneratorChown import InputOutputInfoGeneratorChown as IO
from ParallelizabilityInfoGeneratorChown import ParallelizabilityInfoGeneratorChown as PAR
js = json.load(open(os.environ["OUT"]+"/annotation/chown.json"))
print("syntaxes:", len(chown_syntax_spec))
for i,s in enumerate(chown_syntax_spec):
    print(f" syntax {i}: {len(s[0])} option nodes; positionals: {s[1]}")

# collect spellings from spec and json
spec_flags=set(); spec_opts={}
for s in chown_syntax_spec:
    for n in s[0]:
        names=[n.flag]+n.alias
        if type(n).__name__=="Flag": spec_flags.update(names)
        else:
            for x in names: spec_opts[x]=type(n).__name__
json_flags={x for e in js["flag"] for x in ([e] if isinstance(e,str) else e)}
json_opts={x:e[-1] for e in js["option"] for x in e[:-1]}
print("spec==json flags:", spec_flags==json_flags, spec_flags^json_flags)
print("spec==json options:", set(spec_opts)==set(json_opts), set(spec_opts)^set(json_opts))

# every option in --help appears in spec, and vice versa
import re
helptxt=subprocess.run(["chown","--help"],capture_output=True,text=True).stdout
help_opts=set(re.findall(r"(?<![\w-])(--?[A-Za-z][\w-]*)", helptxt))
help_opts={o for o in help_opts if o not in ("-", )}
print("in --help but not in spec:", help_opts-(spec_flags|set(spec_opts)))
print("in spec but not in --help:", (spec_flags|set(spec_opts))-help_opts)

# test binary: each flag accepted; each option requires an argument
d=tempfile.mkdtemp(); f=os.path.join(d,"f"); open(f,"w").close(); me=os.getlogin() if False else subprocess.run(["id","-un"],capture_output=True,text=True).stdout.strip()
bad=[]
for fl in sorted(spec_flags):
    if fl in ("--help","--version"): continue
    r=subprocess.run(["chown",fl,me,f],capture_output=True,text=True)
    if r.returncode!=0 and "invalid option" in r.stderr or "unrecognized" in r.stderr: bad.append((fl,r.stderr))
    # flags must NOT accept an argument
    r=subprocess.run(["chown",fl+"=x",me,f],capture_output=True,text=True) if fl.startswith("--") else None
    if r is not None and "doesn't allow an argument" not in r.stderr: bad.append((fl,"accepted =arg?",r.stderr))
for op in sorted(spec_opts):
    r=subprocess.run(["chown",op],capture_output=True,text=True)
    if "requires an argument" not in r.stderr: bad.append((op,"no arg required?",r.stderr))
    arg = f if op=="--reference" else me
    for form in ([op+"="+arg],[op,arg]):
        r=subprocess.run(["chown",*form,*([] if op=="--reference" else [me]),f],capture_output=True,text=True)
        if r.returncode!=0: bad.append((form,r.stderr))
print("binary disagreements:", bad or "none")

# IO generator behaviour
for flags,ops in [([],[me,"a","b"]),(["--reference"],["a","b"]),(["-v"],[me,"a"]),(["-c","--reference"],["a"])]:
    g=IO(flags,ops); g.generate_info()
    print(f"IO {flags} {ops}: stdin={g.stdin} stdout={g.stdout} config={g.config} inputs={g.inputs} outputs={g.outputs}")
p=PAR(["-R"],[me,"a"]); p.generate_info(); print("parallelizers:", p.parallelizers)
EOF

